'use strict';
/*
 * The demo's bundle (scripts/build-demo.mjs): the library's own src/ with stand-ins for Node, run here
 * in a bare vm context that has only what a browser has. No browser needed: this checks the build and
 * the stand-ins; test/demo.browser.test.js checks the page.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const pathShim = require('../scripts/browser-shims/path');
const { Buffer: ShimBuffer } = require('../scripts/browser-shims/buffer');
const { version } = require('../package.json');

let bundle;
test.before(async () => {
  bundle = await (await import('../scripts/build-demo.mjs')).buildDemo();
});

/** The bundle in a context with a browser's globals only: no require, no process, no Buffer. */
function load() {
  const sandbox = { TextEncoder, TextDecoder, crypto: globalThis.crypto, setTimeout, clearTimeout, console };
  sandbox.globalThis = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(bundle, sandbox, { filename: 'ai-threads.js' });
  return sandbox.AiThreads;
}

const SID = 'demo-session';
/** A value from the vm context, as plain JSON of this one (deepStrictEqual compares prototypes across contexts). */
const plain = (value) => JSON.parse(JSON.stringify(value));
const tick = () => new Promise((r) => setTimeout(r, 5));

test('the bundle defines AiThreads with no Node in reach, and says what it was built from', () => {
  assert.match(bundle, new RegExp(`^/\\*! ai-threads v${version.replace(/\./g, '\\.')} for the browser demo \\| MIT`));
  assert.match(bundle, /Generated by scripts\/build-demo\.mjs/);
  const A = load();
  assert.equal(A.version, version);
  assert.deepEqual(plain(Object.keys(A).sort()), ['fs', 'makeHooks', 'markup', 'open', 'version']);
  assert.equal(A.markup.mark(3, 'Deploy fails'), '[Q3 · Deploy fails]');
});

test('the real library runs on it: start hook, a watched signal, the wake hook, the transcript and view()', async () => {
  const A = load();
  let clock = Date.parse('2026-11-14T10:00:00Z');
  const now = () => clock;
  const at = A.open({ home: '/home', claudeDir: '/claude', env: {}, now, liveness: () => ({ known: true, alive: true, busy: false, startedAt: clock - 1000 }), spawnToucher() {}, runCommand() {} });
  const hooks = A.makeHooks(at, { env: {} });
  const file = '/claude/projects/p/demo-session.jsonl';
  A.fs.mkdirSync('/claude/projects/p', { recursive: true });
  A.fs.writeFileSync(file, '');
  const started = JSON.parse(hooks.start({ session_id: SID, source: 'startup', transcript_path: file }).stdout);
  assert.deepEqual(plain(started.hookSpecificOutput.watchPaths), [`/home/sessions/${SID}/signal`]);
  let touched = 0;
  A.fs.watch(started.hookSpecificOutput.watchPaths[0], () => { touched += 1; });

  clock += 1000;
  const sent = at.deliverSync(SID, 'Is the deploy fixed?');
  await tick();
  assert.equal(touched, 1, 'the watch saw the touch');
  assert.deepEqual(plain(at.view(SID).threads.map((t) => [t.id, t.state])), [['q1', 'queued']]);

  clock += 1000;
  const out = hooks.wake({ session_id: SID, file_path: started.hookSpecificOutput.watchPaths[0] });
  assert.equal(out.code, 2);
  assert.match(out.stderr, /^This session is followed in an app[\s\S]*\n\n\[Q1 · Is the deploy fixed\?\] Is the deploy fixed\?$/, 'the instruction, once, then the batch');
  const line = (entry) => A.fs.appendFileSync(file, `${JSON.stringify(entry)}\n`);
  line({ type: 'user', uuid: 'u1', timestamp: new Date(clock).toISOString(), message: { role: 'user', content: `<system-reminder>\nai-threads: messages for this session. ${out.stderr}\n</system-reminder>` } });
  clock += 1000;
  line({ type: 'assistant', uuid: 'a1', timestamp: new Date(clock).toISOString(), message: { role: 'assistant', content: [{ type: 'text', text: 'Yes, fixed.\n\n[Q new · Bump the version?]\nShould I bump it?' }] } });

  const v = at.view(SID, { persist: true });
  assert.deepEqual(plain(v.threads.map((t) => [t.n, t.title, t.origin, t.messages.map((m) => [m.from, m.text, m.state || null])])), [
    [1, 'Is the deploy fixed?', '', [['me', 'Is the deploy fixed?', 'read'], ['other', 'Yes, fixed.', null]]],
    [2, 'Bump the version?', 'opened by the session', [['other', 'Should I bump it?', null]]],
  ]);
  assert.equal(v.threads[0].messages[0].id, sent.id);
  assert.ok(A.fs.list().some((f) => f.path === `/home/sessions/${SID}/delivered/${sent.id}.json`), 'claimed by a rename into delivered/');
});

test('the file system in memory answers with the codes the library decides by', async () => {
  const { fs } = load();
  assert.throws(() => fs.readFileSync('/nope'), { code: 'ENOENT' });
  assert.throws(() => fs.writeFileSync('/a/b.txt', 'x'), { code: 'ENOENT' }, 'no parent folder');
  assert.throws(() => fs.mkdirSync('/a/b'), { code: 'ENOENT' });
  fs.mkdirSync('/a/b', { recursive: true });
  assert.throws(() => fs.mkdirSync('/a/b'), { code: 'EEXIST' });
  fs.mkdirSync('/a/b', { recursive: true });

  fs.writeFileSync('/a/b/one.json', '{"n":1}', { flag: 'wx' });
  assert.throws(() => fs.writeFileSync('/a/b/one.json', 'again', { flag: 'wx' }), { code: 'EEXIST' });
  fs.appendFileSync('/a/b/log', 'é\n');
  fs.appendFileSync('/a/b/log', 'two\n');
  assert.equal(fs.readFileSync('/a/b/log', 'utf8'), 'é\ntwo\n');
  assert.equal(fs.readFileSync('/a/b/log', { encoding: 'utf8' }), 'é\ntwo\n');
  assert.equal(fs.statSync('/a/b/log').size, 7, 'bytes, not characters');
  assert.equal(fs.statSync('/a/b').isDirectory(), true);
  assert.deepEqual(plain(fs.readdirSync('/a/b')), ['log', 'one.json']);
  assert.deepEqual(plain(fs.readdirSync('/a')), ['b'], 'only the folder\'s own entries');

  const seen = [];
  fs.watch('/a/b/two.json', (event, name) => seen.push([event, name]));
  fs.renameSync('/a/b/one.json', '/a/b/two.json');
  await tick();
  assert.deepEqual(seen, [['change', 'two.json']], 'a rename onto a watched file is a change');
  assert.equal(fs.existsSync('/a/b/one.json'), false);
  assert.throws(() => fs.renameSync('/a/b/one.json', '/a/b/x'), { code: 'ENOENT' });

  // a lock file: open with wx once, write, read back by position, close, remove
  const fd = fs.openSync('/a/b/lock', 'wx');
  assert.throws(() => fs.openSync('/a/b/lock', 'wx'), { code: 'EEXIST' });
  fs.writeSync(fd, '1234');
  fs.closeSync(fd);
  const rd = fs.openSync('/a/b/lock', 'r');
  const buf = new Uint8Array(2);
  assert.equal(fs.readSync(rd, buf, 0, 2, 1), 2);
  assert.deepEqual([...buf], [50, 51]);
  fs.closeSync(rd);
  fs.unlinkSync('/a/b/lock');
  assert.throws(() => fs.unlinkSync('/a/b/lock'), { code: 'ENOENT' });
  assert.throws(() => fs.writeSync(fd, 'x'), { code: 'EBADF' });
  assert.deepEqual(plain(fs.list().map((f) => f.path)), ['/a/b/log', '/a/b/two.json']);
});

test('POSIX paths: join, resolve, dirname, basename, extname', () => {
  assert.equal(pathShim.join('/home', 'sessions', 'a', '..', 'b'), '/home/sessions/b');
  assert.equal(pathShim.join('a', '', 'b'), 'a/b');
  assert.equal(pathShim.resolve('/home', 'x'), '/home/x');
  assert.equal(pathShim.resolve('/home', '/abs', 'y'), '/abs/y');
  assert.equal(pathShim.resolve('rel'), '/rel', 'the working folder is /');
  assert.equal(pathShim.normalize('/a//b/./c/'), '/a/b/c');
  assert.equal(pathShim.normalize('/..'), '/');
  assert.equal(pathShim.dirname('/a/b/c.json'), '/a/b');
  assert.equal(pathShim.dirname('/a'), '/');
  assert.equal(pathShim.dirname('a'), '.');
  assert.equal(pathShim.basename('/a/b/c.json'), 'c.json');
  assert.equal(pathShim.basename('/a/b/c.json', '.json'), 'c');
  assert.equal(pathShim.extname('/a/b/c.json'), '.json');
  assert.equal(pathShim.extname('/a/.hidden'), '');
});

test('Buffer: alloc, from, hex and utf8, and subarray keeps the type', () => {
  const b = ShimBuffer.from('a\nb\n');
  assert.equal(b.lastIndexOf(0x0a), 3);
  assert.equal(b.toString('utf8', 0, 3), 'a\nb');
  assert.ok(b.subarray(0, 1) instanceof ShimBuffer);
  assert.equal(ShimBuffer.from([0, 15, 255]).toString('hex'), '000fff');
  assert.equal(ShimBuffer.alloc(3).length, 3);
});
